#include <bits/stdc++.h>
using namespace std;

long long pow_mod(long long a, long long n, long long mod) {
    long long ret = 1;
    for (int x = 63 - __builtin_clzll(n); x >= 0; x--) {
        ret = ret * ret % mod;
        if ((n << (63 - x)) < 0)
            ret = ret * a % mod;
    }
    return ret;
}

long long C(int n, int r, int mod, vector<vector<int>>& fif) {
    if (n < 0 || r < 0 || r > n)
        return 0;
    return (long long)fif[0][n] * fif[1][r] % mod * fif[1][n - r] % mod;
}

vector<vector<int>> enumFIF(int n, int mod) {
    vector<int> f(n + 1), invf(n + 1);
    f[0] = 1;
    for (int i = 1; i <= n; i++) {
        f[i] = (long long)f[i - 1] * i % mod;
    }
    long long a = f[n], b = mod;
    long long p = 1, q = 0;
    while (b > 0) {
        long long c = a / b;
        long long d = a;
        a = b;
        b = d % b;
        d = p;
        p = q;
        q = d - c * q;
    }
    invf[n] = (int)(p < 0 ? p + mod : p);
    for (int i = n - 1; i >= 0; i--) {
        invf[i] = (int)((long long)invf[i + 1] * (i + 1) % mod);
    }
    return {f, invf};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int mod = 998244353;
    int n;
    long long K;
    cin >> n >> K;
    if (K >= n) {
        cout << 0 << "\n";
        return 0;
    }
    auto fif = enumFIF(250000, mod);
