        return 0;
    }
    long long ans = 0;
    for (int i = n - (int)K, s = 1; i >= 1; i--, s = mod - s) {
        long long term = C(n, i, mod, fif) * pow_mod(i, n, mod) % mod;
        term = term * s % mod;
        term = term * C((int)(n - i), (int)K, mod, fif) % mod;
        ans = (ans + term) % mod;
    }
    ans = ans * 2 % mod;
    cout << ans << "\n";
